function clamp01(v) { return Math.max(0, Math.min(1, v)); }
function smoother(p) { return p*p*p*(10+p*(-15+6*p)); }
function ease(t, a, b) { return smoother(clamp01((t-a)/(b-a))); }
function wave(p, t, amplitude, sign) { return sign*amplitude*Math.sin(p*Math.PI*5-t*0.0024); }
export default defineSpanScene({
  id: "explainer-steps", width: 1920, height: 1080, durationMs: 24000, editPreviewMs: 14500,
  variables: {
    title: stringVar("How noise cancellation works"),
    step1: stringVar("A microphone listens to the noise."),
    step2: stringVar("The speaker makes an opposite wave."),
    step3: stringVar("Together, they reduce the rumble."),
    takeaway: stringVar("Best for steady, low sounds."),
    caveat: stringVar("Noise cancellation reduces noise. It does not create complete silence."),
    accent: colorVar("#BD5832"), counter: colorVar("#758365"), ink: colorVar("#21333C"), paper: colorVar("#F7ECD5"),
  },
  computeds: {
    clock: computed.number(() => time.ms),
    focus: computed.number(() => ease(computed.clock,2800,6500)*(1-ease(computed.clock,20000,22400))),
    zoom: computed.number(() => 1+0.34*computed.focus),
    panel: computed.number(() => ease(computed.clock,3200,4100)*(1-ease(computed.clock,20100,21100))),
    intro: computed.number(() => ease(computed.clock,100,800)*(1-ease(computed.clock,2600,3200))),
    opposite: computed.number(() => ease(computed.clock,8000,10000)),
    merge: computed.number(() => ease(computed.clock,13700,16300)),
    settle: computed.number(() => ease(computed.clock,16000,17900)),
    ending: computed.number(() => ease(computed.clock,21700,22600)),
    step: computed.number(() => computed.clock<8000?1:computed.clock<13700?2:3),
    noise: computed.points(() => collection.map(collection.range(181),(index,p) => ({x: 150+860*p, y: 530+64*computed.merge+wave(p,computed.clock,64,1)}))),
    anti: computed.points(() => collection.map(collection.range(181),(index,p) => ({x: 150+860*p, y: 760-166*computed.merge+wave(p,computed.clock,64,-1)}))),
    residual: computed.points(() => collection.map(collection.range(181),(index,p) => ({x: 150+860*p, y: 594+wave(p,computed.clock,64*(1-0.94*computed.settle),1)}))),
  },
  render({vars,computed}) {
    return <Scene width={1920} height={1080}>
      <Rect id="paper" width={1920} height={1080} fill={vars.paper}/>
      <Group id="train-camera" width={0} height={0} pivotX={0} pivotY={0} x={-440*computed.focus} y={-90*computed.focus} scaleX={computed.zoom} scaleY={computed.zoom}>
        <Image id="moving-countryside" src="data:image/png;base64," x={-100-computed.clock*0.016} y={0} width={2520} height={1080}/>
        <Image id="train-interior" src="data:image/png;base64," width={1920} height={1080}/>
        <Image id="passenger" src="data:image/png;base64," x={0.35*Math.sin(computed.clock*0.006)} y={0.45*Math.sin(computed.clock*0.005)} width={1920} height={1080}/>
        <Ellipse id="microphone-halo" x={1373-6*Math.sin(computed.clock*0.004)} y={356-6*Math.sin(computed.clock*0.004)} width={38+12*Math.sin(computed.clock*0.004)} height={38+12*Math.sin(computed.clock*0.004)} fill="none" stroke={vars.accent} strokeWidth={2} opacity={0.55*computed.panel}/>
        <Ellipse id="microphone" x={1385} y={368} width={14} height={14} fill={vars.accent} opacity={computed.panel}/>
      </Group>
      <Group id="opening-title" width={0} height={0} pivotX={0} pivotY={0} y={14*(1-computed.intro)} opacity={computed.intro}>
        <Text id="opening" text={vars.title} x={100} y={115} width={900} height={210} fontFamily="Inter" fontWeight={600} fontSize={76} lineHeight={1.08} color={vars.ink}/>
        <Rect id="opening-rule" x={104} y={355} width={92} height={5} radius={2.5} fill={vars.accent}/>
      </Group>
      <Group id="explanation" width={0} height={0} pivotX={0} pivotY={0} opacity={computed.panel}>
        <Rect id="diagram-paper" x={72} y={90} width={1050} height={854} radius={24} fill={vars.paper} opacity={0.97}/>
        <Text id="step-number" text={computed.step===1?"01 / 03":computed.step===2?"02 / 03":"03 / 03"} x={120} y={131} width={400} height={35} fontFamily="Inter" fontSize={21} fontWeight={600} letterSpacing={2} color={vars.accent}/>
        <Text id="step-title" text={computed.step===1?vars.step1:computed.step===2?vars.step2:vars.step3} x={120} y={193} width={905} height={205} fontFamily="Inter" fontSize={58} fontWeight={600} lineHeight={1.12} color={vars.ink}/>
        <Group id="incoming-wave" width={0} height={0} pivotX={0} pivotY={0} opacity={1-0.87*computed.settle}>
          <Text id="incoming-label" text="Outside noise" x={150} y={419} width={600} height={38} fontFamily="Inter" fontSize={25} fontWeight={500} color={vars.accent} opacity={1-computed.merge}/>
          <Path id="noise-wave" points={computed.noise} width={1920} height={1080} fill="none" stroke={vars.accent} strokeWidth={5} strokeLineCap="round" strokeLineJoin="round"/>
        </Group>
        <Group id="opposite-wave" width={0} height={0} pivotX={0} pivotY={0} opacity={computed.opposite*(1-0.87*computed.settle)}>
          <Text id="opposite-label" text="Opposite sound" x={150} y={649} width={600} height={38} fontFamily="Inter" fontSize={25} fontWeight={500} color={vars.counter} opacity={1-computed.merge}/>
          <Path id="anti-wave" points={computed.anti} width={1920} height={1080} fill="none" stroke={vars.counter} strokeWidth={5} strokeLineCap="round" strokeLineJoin="round"/>
        </Group>
        <Group id="result" width={0} height={0} pivotX={0} pivotY={0} opacity={computed.settle}>
          <Text id="result-label" text="Less noise at your ear" x={150} y={450} width={800} height={50} fontFamily="Inter" fontSize={30} fontWeight={500} color={vars.ink}/>
          <Path id="residual-wave" points={computed.residual} width={1920} height={1080} fill="none" stroke={vars.ink} strokeWidth={5} strokeLineCap="round" strokeLineJoin="round"/>
          <Text id="result-note" text="The two waves partially cancel." x={150} y={726} width={800} height={80} fontFamily="Inter" fontSize={29} color={vars.ink}/>
        </Group>
        <Rect id="progress-track" x={120} y={886} width={948} height={4} radius={2} fill="#DED1B7"/>
        <Rect id="progress-fill" x={120} y={886} width={948*clamp01((computed.clock-3400)/16300)} height={4} radius={2} fill={vars.accent}/>
      </Group>
      <Group id="ending" width={0} height={0} pivotX={0} pivotY={0} opacity={computed.ending} y={10*(1-computed.ending)}>
        <Text id="takeaway" text={vars.takeaway} x={100} y={110} width={920} height={190} fontFamily="Inter" fontSize={69} fontWeight={600} lineHeight={1.1} color={vars.ink}/>
        <Text id="caveat" text={vars.caveat} x={104} y={340} width={820} height={125} fontFamily="Inter" fontSize={29} lineHeight={1.3} color={vars.ink}/>
      </Group>
    </Scene>;
  },
});
